@app.get("/v1/cases/{case_id}")
async def read_case(
    case_id: str,
    user: Annotated[str, Security(
        get_current_user, scopes=["cases:read"])],
) -> dict:
    if case_id not in CASES:
        raise HTTPException(404, "no such case")
    if CASES[case_id] != user:
        raise HTTPException(403, "not yours")
    return {"id": case_id}
